<?php
$q=trim((string)($_GET['historico']??''));$situacao=$_GET['situacao']??'todos';$ini=$_GET['data_ini']??'';$fim=$_GET['data_fim']??'';
$lista=array_values(array_filter($itens,function($i)use($q,$ini,$fim,$situacao){return $i['status']!=='ESTORNADO'&&(!$q||stripos($i['descricao'],$q)!==false)&&(!$ini||$i['data_compra']>=$ini)&&(!$fim||$i['data_compra']<=$fim)&&($situacao==='todos'||($situacao==='conciliados'?!empty($i['cpcontador']):empty($i['cpcontador'])));}));
$itensPorId=array_column($itens,null,'id');
$s=$pdo_master->prepare("SELECT debito_id,credito_id,valor FROM financeiro_cc_estornos WHERE fatura_id=? AND empresa_id=? ORDER BY debito_id");$s->execute([$faturaId,$empresa]);$estornos=$s->fetchAll(PDO::FETCH_ASSOC);
$totalEstornado=array_sum(array_column($estornos,'valor'));
$debitosEstornaveis=array_values(array_filter($itens,static function($i){return $i['natureza']==='D' && $i['status']!=='ESTORNADO' && !$i['cpcontador'];}));
$creditosEstornaveis=array_values(array_filter($itens,static function($i){return $i['natureza']==='C' && $i['status']!=='ESTORNADO' && !$i['cpcontador'];}));
$s=$pdo_master->prepare("SELECT e.id,e.debito_id,e.valor,d.descricao,d.cpcontador,f.competencia,f.status AS status_origem,COALESCE(SUM(a.valor),0) AS aplicado,cp.TIPOES AS cp_tipoes,t.CONTRAP_CBCONTADOR,t.CONTRAP_TIPOES FROM financeiro_cc_creditos_esperados e JOIN financeiro_cc_itens d ON d.id=e.debito_id JOIN financeiro_cc_faturas f ON f.id=d.fatura_id LEFT JOIN financeiro_cc_creditos_aplicados a ON a.esperado_id=e.id LEFT JOIN armazem_cp001 cp ON cp.EMPRESA=e.empresa_id AND cp.CPCONTADOR=d.cpcontador LEFT JOIN armazem_bnc005 t ON t.EMPRESA=cp.EMPRESA AND t.ESCONTADOR=cp.TIPOES WHERE e.empresa_id=? AND e.cartao_id=? GROUP BY e.id,e.debito_id,e.valor,d.descricao,d.cpcontador,f.competencia,f.status,cp.TIPOES,t.CONTRAP_CBCONTADOR,t.CONTRAP_TIPOES ORDER BY f.competencia,d.id");
$s->execute([$empresa,(int)$fatura['cartao_id']]);$creditosEsperados=$s->fetchAll(PDO::FETCH_ASSOC);
$esperadosOrigem=array_values(array_filter($creditosEsperados,static function($e)use($itensPorId){return isset($itensPorId[$e['debito_id']]);}));
$creditosRecebidos=array_values(array_filter($itens,static function($i){return $i['natureza']==='C' && $i['status']!=='ESTORNADO';}));
$s=$pdo_master->prepare("SELECT a.credito_id,a.esperado_id,a.valor,a.mov_credito_39 FROM financeiro_cc_creditos_aplicados a JOIN financeiro_cc_itens i ON i.id=a.credito_id WHERE i.fatura_id=? AND a.empresa_id=?");$s->execute([$faturaId,$empresa]);$aplicadosPorCredito=array_column($s->fetchAll(PDO::FETCH_ASSOC),null,'credito_id');
$s=$pdo_master->prepare("SELECT a.credito_id,a.valor,a.mov_credito_39 FROM financeiro_cc_creditos_avulsos a JOIN financeiro_cc_itens i ON i.id=a.credito_id WHERE i.fatura_id=? AND a.empresa_id=?");$s->execute([$faturaId,$empresa]);$avulsosPorCredito=array_column($s->fetchAll(PDO::FETCH_ASSOC),null,'credito_id');
$creditosSemClassificacao=array_values(array_filter($creditosRecebidos,static function($c)use($aplicadosPorCredito,$avulsosPorCredito){return !isset($aplicadosPorCredito[$c['id']]) && !isset($avulsosPorCredito[$c['id']]);}));
$creditosEstornaveis=array_values(array_filter($creditosEstornaveis,static function($c)use($aplicadosPorCredito,$avulsosPorCredito){return !isset($aplicadosPorCredito[$c['id']]) && !isset($avulsosPorCredito[$c['id']]);}));
$debitosEstornaveis=array_values(array_filter($debitosEstornaveis,static function($d)use($creditosEsperados){return !in_array((int)$d['id'],array_map('intval',array_column($creditosEsperados,'debito_id')),true);}));
$paresEstornaveis=[];
foreach($creditosEstornaveis as $credito){
    $debitosMesmoValor=array_values(array_filter($debitosEstornaveis,static function($debito)use($credito){return (int)round((float)$debito['valor']*100)===(int)round((float)$credito['valor']*100);}));
    if($debitosMesmoValor)$paresEstornaveis[]=['credito'=>$credito,'debitos'=>$debitosMesmoValor];
}
$idsCreditosEstornaveis=array_fill_keys(array_map(static function($par){return (int)$par['credito']['id'];},$paresEstornaveis),true);
$creditosParaClassificar=array_values(array_filter($creditosRecebidos,static function($credito)use($idsCreditosEstornaveis){return !isset($idsCreditosEstornaveis[(int)$credito['id']]);}));
$pendentesParaClassificar=array_values(array_filter($creditosSemClassificacao,static function($credito)use($idsCreditosEstornaveis){return !isset($idsCreditosEstornaveis[(int)$credito['id']]);}));
$candidatosCredito=array_values(array_filter($creditosEsperados,static function($e)use($fatura){return $e['status_origem']==='ENCERRADA' && $e['competencia']<$fatura['competencia'] && (int)round(((float)$e['valor']-(float)$e['aplicado'])*100)>0;}));
$chaveEstorno=static function(string $descricao):string{return preg_replace('/^(EST|REV|AJUSTE CR)\s+/','',normalizarDescricaoCartao($descricao));};
$sugestoesOrigem=[];
if($creditosRecebidos){
    $valores=array_values(array_unique(array_map(static function($c){return number_format((float)$c['valor'],2,'.','');},$creditosRecebidos)));
    $marcadores=implode(',',array_fill(0,count($valores),'?'));
    $s=$pdo_master->prepare("SELECT d.id,d.descricao,d.valor,f.id AS fatura_id,f.competencia,f.status FROM financeiro_cc_itens d JOIN financeiro_cc_faturas f ON f.id=d.fatura_id AND f.empresa_id=d.empresa_id WHERE f.empresa_id=? AND f.cartao_id=? AND f.competencia<? AND d.natureza='D' AND d.status<>'ESTORNADO' AND d.cpcontador IS NOT NULL AND d.valor IN ($marcadores) ORDER BY f.competencia DESC,d.id DESC");
    $s->execute(array_merge([$empresa,(int)$fatura['cartao_id'],$fatura['competencia']],$valores));
    foreach($s as $origem){$chave=number_format((float)$origem['valor'],2,'.','').'|'.$chaveEstorno((string)$origem['descricao']);if(count($sugestoesOrigem[$chave]??[])<3)$sugestoesOrigem[$chave][]=$origem;}
}
$vinculados=array_values(array_filter($lista,static function($i){return $i['natureza']==='D'&&!empty($i['cpcontador']);}));
$sqlCp="SELECT cp.CPCONTADOR,cp.DTCOMPRA,cp.DTVENC,cp.TITULO,COALESCE(NULLIF(cp.VLRRESTANTE,0),cp.VLRPARCELA,cp.VALORCOMPRA) valor,COALESCE(NULLIF(f.APELIDO,''),f.NOME) fornecedor FROM armazem_cp001 cp LEFT JOIN armazem_cp003 f ON f.EMPRESA=cp.EMPRESA AND f.FCONTADOR=cp.FCONTADOR WHERE cp.EMPRESA=? AND cp.STATUS<>'QT' AND cp.DTPAGTO IS NULL AND COALESCE(cp.VLRPAGO,0)=0 AND COALESCE(cp.excluido_firebird,'N')<>'S' AND NOT EXISTS(SELECT 1 FROM financeiro_cc_itens x WHERE x.empresa_id=cp.EMPRESA AND x.cpcontador=cp.CPCONTADOR)";$parCp=[$empresa];if($ini){$sqlCp.=" AND DATE(cp.DTCOMPRA)>=?";$parCp[]=$ini;}if($fim){$sqlCp.=" AND DATE(cp.DTCOMPRA)<=?";$parCp[]=$fim;}if($q){$sqlCp.=" AND (cp.TITULO LIKE ? OR f.NOME LIKE ? OR f.APELIDO LIKE ?)";$busca='%'.$q.'%';array_push($parCp,$busca,$busca,$busca);}$sqlCp.=" ORDER BY cp.DTCOMPRA DESC,cp.CPCONTADOR DESC";$stmtCp=$pdo_master->prepare($sqlCp);$stmtCp->execute($parCp);$cpSistema=$stmtCp->fetchAll(PDO::FETCH_ASSOC);
$seguros=[];$manual=[];$sem=[];$contagens=cccContarValoresPendentes($lista);
foreach($lista as $i){
    if($i['natureza']!=='D'||$i['cpcontador'])continue;
    $c=cccCandidatos($pdo_master,$i,$fatura['vencimento']);
    $automatico=cccCandidatoAutomatico($i,$c,$contagens,$fatura['vencimento']);
    if($automatico)$seguros[]=[$i,$automatico];
    elseif($c)$manual[]=[$i,$c];
    else $sem[]=$i;
}
function ccForm(int $fid,int $iid,int $cp):string{return '<form method="post"><input type="hidden" name="acao" value="vincular"><input type="hidden" name="fatura_id" value="'.$fid.'"><input type="hidden" name="item_id" value="'.$iid.'"><input type="hidden" name="cpcontador" value="'.$cp.'"><button class="btn btn-sm btn-primary">Conciliar</button></form>';}
function ccParcelaExtrato(array $item):string
{
    $tipo=(string)($item['tipo_lancamento']??'');
    return preg_match('/(\d+)\s*\/\s*(\d+)/',$tipo,$m)?$m[1].'/'.$m[2]:'-';
}
