<script>
document.querySelectorAll('.cc-manual-match').forEach(select => {
    select.addEventListener('change', () => {
        const escolhidos = new Set([...document.querySelectorAll('.cc-manual-match')].map(item => item.value).filter(Boolean));
        document.querySelectorAll('.cc-manual-match').forEach(item => {
            [...item.options].forEach(option => {
                option.disabled = option.value !== '' && option.value !== item.value && escolhidos.has(option.value);
                option.hidden = option.disabled;
            });
        });
    });
});
</script>
